// seed.js: resets the database and fills it with demo data for the 16 Nov 2026 presentation.
//
// What it does, in order:
//   1. (WIPE_FIRST) deletes everything in the app's collections, plus the Firebase Auth
//      accounts that belong to the deleted users
//   2. creates Firebase Auth accounts for the demo users (password: TEST_PASSWORD)
//   3. writes users, volunteers, availability, requests, sessions, feedback and notifications
//
// Every document ID is generated by Firebase (users are keyed by their Auth UID).
// Run it from the database folder:  node seed.js
// Dates are written as Date values (Malaysia time, +08:00); Firestore stores them as Timestamps.

import { readFileSync } from "node:fs";
import { initializeApp, cert } from "firebase-admin/app";
import { getFirestore } from "firebase-admin/firestore";
import { getAuth } from "firebase-admin/auth";

const SERVICE_ACCOUNT_PATH = "./secrets/service-account.json"; // path to service account key JSON
const WIPE_FIRST = true;           // keep true, otherwise every run adds duplicate records
const TEST_PASSWORD = "Test1234!"; // every demo account logs in with this password

const serviceAccount = JSON.parse(readFileSync(SERVICE_ACCOUNT_PATH, "utf8"));
const app = initializeApp({ credential: cert(serviceAccount) });
const db = getFirestore(app);
const auth = getAuth(app);

